import csv as _csv
import datetime as _dt
from pathlib import Path

_START = _dt.date(2026, 1, 1)
_END = _dt.date(2026, 12, 31)
_ONE = _dt.timedelta(days=1)
_REGION_ORDER = ["North", "South", "West", "East"]
_SUM_FIELDS = ["water_supply_cents", "wastewater_cents", "service_charges_cents", "surcharge_cents", "catchment_levy_cents",
               "trade_waste_cents", "gross_charge_cents", "rebates_total_cents", "minimum_topup_cents", "net_charge_cents",
               "payments_cents", "interest_cents", "balance_cents"]
_Q_FIRST_DAY = {"Q1": _dt.date(2026, 1, 1), "Q2": _dt.date(2026, 4, 1), "Q3": _dt.date(2026, 7, 1), "Q4": _dt.date(2026, 10, 1)}


def _div_round(n, d, ties_up):
    """Integer n/d (d > 0) rounded to the nearest integer; ties go up, or to the even neighbour."""
    q, r = divmod(n, d)
    twice = 2 * r
    if twice > d or (twice == d and (ties_up or q % 2 == 1)):
        q += 1
    return q


def _day(s):
    return _dt.date.fromisoformat(s)


def _table(path):
    with open(path, newline="", encoding="utf-8") as fh:
        return [dict(r) for r in _csv.DictReader(fh)]


def _figure_on(plist, when):
    for per in plist:
        last = _day(per["to"]) if per["to"] is not None else _dt.date.max
        if _day(per["from"]) <= when <= last:
            return per["rate"] if "rate" in per else per["rate_ppm"]
    raise LookupError(when)


class _Daily:
    def __init__(self):
        self.memo = {}

    def total(self, tag, plist, first, last):
        """Sum of the daily figure over first..last inclusive."""
        if last < first:
            return 0
        table = self.memo.get(tag)
        if table is None:
            table = {}
            cursor = _START
            while cursor <= _END:
                table[cursor] = _figure_on(plist, cursor)
                cursor += _ONE
            self.memo[tag] = table
        acc, cursor = 0, first
        while cursor <= last:
            acc += table[cursor]
            cursor += _ONE
        return acc


def _qualifies(rb, ctx):
    rule = rb["elig"]
    checks = [
        ("classes" not in rule) or ctx["acls"] in rule["classes"],
        ("cards" not in rule) or ctx["card"] in rule["cards"],
        (not rule.get("drought_property")) or ctx["dprop"],
        (not rule.get("community")) or ctx["comm"],
        (not rule.get("large_meter")) or ctx["large"],
        ctx["form"] not in rule.get("excluded", []),
    ]
    return all(checks)


def _interest_on(rules, amount, due, until):
    rate_days, cursor = 0, due + _ONE
    while cursor <= until:
        rate_days += _figure_on(rules["interest"], cursor)
        cursor += _ONE
    return _div_round(amount * rate_days, 365_000_000, True)


def expected_statements(data_dir, rules):
    data_dir = Path(data_dir)
    manifest = _json.loads((data_dir / "batch.json").read_text(encoding="utf-8"))
    assess_day = _day(manifest["assessment_date"])
    T = {n: _table(data_dir / n) for n in ("accounts.csv", "properties.csv", "meters.csv", "meter_reads.csv", "trade_waste.csv",
                                           "concession_claims.csv", "leak_claims.csv", "carryforwards.csv", "payments.csv")}
    rulings = rules["rulings"]
    hols = set(_day(h) for h in rules["holidays"])
    due_of = {k: _day(v) for k, v in rules["audit"]["instalment_due_dates"].items()}
    daily = _Daily()
    notes = []

    def group(rows, field):
        g = {}
        for r in rows:
            g.setdefault(r[field], []).append(r)
        return g
    P, M, R = group(T["properties.csv"], "account_id"), group(T["meters.csv"], "property_id"), group(T["meter_reads.csv"], "meter_id")
    TW, LK = group(T["trade_waste.csv"], "property_id"), group(T["leak_claims.csv"], "property_id")
    CL, CF, PY = group(T["concession_claims.csv"], "account_id"), group(T["carryforwards.csv"], "account_id"), group(T["payments.csv"], "account_id")
    code_map = {rb["code"]: rb for rb in rules["rebates"]}

    assessed = []
    for a in sorted(T["accounts.csv"], key=lambda x: x["account_id"]):
        acc_id = a["account_id"]
        open_from = _START if _day(a["opened_on"]) < _START else _day(a["opened_on"])
        open_to = _END if not a["closed_on"] or _day(a["closed_on"]) > _END else _day(a["closed_on"])
        n_active = (open_to - open_from).days + 1 if open_to >= open_from else 0
        lines, mrows, prows = [], [], []
        by_zone_litres = {}
        sums = dict(water=0, ww=0, svc=0, storm=0, trade=0, levy_base=0, big=0)
        alive = []
        for pr in sorted(P.get(acc_id, []), key=lambda x: x["property_id"]):
            klass = rules["classes"][pr["tariff_class"]]
            zone = rules["zones"][pr["zone"]]
            w_from = max(open_from, _day(pr["connected_on"]))
            w_to = open_to if not pr["disconnected_on"] else min(open_to, _day(pr["disconnected_on"]))
            n_prop = (w_to - w_from).days + 1 if w_to >= w_from else 0
            if n_prop > 0:
                alive.append(pr)
            low, high = rules["thresholds"][klass["band"]]
            water_here = 0
            for mt in sorted(M.get(pr["property_id"], []), key=lambda x: x["meter_id"]):
                s_from = max(w_from, _day(mt["installed_on"]))
                s_to = w_to if not mt["removed_on"] else min(w_to, _day(mt["removed_on"]))
                n_meter = (s_to - s_from).days + 1 if s_to >= s_from else 0
                size = int(mt["size_mm"])
                fee = _div_round(daily.total(("s", size), rules["service"][str(size)], s_from, s_to), 100, False) if n_meter else 0
                sums["svc"] += fee
                if n_meter and size >= 80:
                    sums["big"] += fee
                mrows.append(dict(meter_id=mt["meter_id"], property_id=pr["property_id"], size_mm=size, service_days=n_meter, service_cents=fee))
                kept = []
                for rd in sorted(R.get(mt["meter_id"], []), key=lambda x: x["read_on"]):
                    when = _day(rd["read_on"])
                    if n_meter and s_from - _ONE <= when <= s_to:
                        kept.append((when, int(rd["reading_litres"])))
                    else:
                        notes.append("%s: reading of %s outside the meter's supply window disregarded" % (mt["meter_id"], rd["read_on"]))
                for k in range(1, len(kept)):
                    d_prev, v_prev = kept[k - 1]
                    d_cur, v_cur = kept[k]
                    span = (d_cur - d_prev).days
                    litres = v_cur - v_prev
                    if litres < 0:
                        notes.append("%s: reading of %s lower than the preceding reading; consumption nil" % (mt["meter_id"], d_cur.isoformat()))
                        litres = 0
                    first_day = d_prev + _ONE
                    b1 = min(litres, low * span)
                    b2 = min(max(litres - low * span, 0), (high - low) * span)
                    b3 = max(litres - high * span, 0)
                    rsum = [daily.total(("r", pr["tariff_class"], j), klass["rates"]["block_%d" % j], first_day, d_cur) for j in (1, 2, 3)]
                    w_cents = _div_round(b1 * rsum[0] + b2 * rsum[1] + b3 * rsum[2], span * 100000, False)
                    wsum = daily.total(("w", pr["zone"]), zone["ww"], first_day, d_cur)
                    ww_cents = _div_round(litres * klass["discharge_percent"] * wsum, span * 100 * 100000, True)
                    lines.append(dict(meter_id=mt["meter_id"], property_id=pr["property_id"], days=span, litres=litres, water_cents=w_cents,
                                      wastewater_cents=ww_cents, to=d_cur.isoformat(), **{"from": first_day.isoformat()}))
                    water_here += w_cents
                    sums["ww"] += ww_cents
                    by_zone_litres[pr["zone"]] = by_zone_litres.get(pr["zone"], 0) + litres
            sums["water"] += water_here
            if not klass["catchment_exempt"]:
                sums["levy_base"] += water_here
            storm_c = _div_round(int(pr["land_area_m2"]) * zone["storm"] * n_prop, 36500, True) if n_prop else 0
            sums["storm"] += storm_c
            tw_c = 0
            for ret in sorted(TW.get(pr["property_id"], []), key=lambda x: x["return_id"]):
                if a["account_class"] != "commercial":
                    notes.append("%s: trade waste return for a property of a non-commercial account disregarded" % ret["return_id"])
                    continue
                q0 = _Q_FIRST_DAY[ret["quarter"]]
                lit = int(ret["discharge_litres"])
                vr = _figure_on(rules["trade_waste"]["volume"], q0)
                lr = _figure_on(rules["trade_waste"]["load"], q0)
                tw_c += _div_round(lit * vr * 1000 + lit * int(ret["bod_mg_per_l"]) * lr, 100_000_000, False)
            sums["trade"] += tw_c
            prows.append(dict(property_id=pr["property_id"], zone=pr["zone"], tariff_class=pr["tariff_class"], supply_days=n_prop,
                              stormwater_cents=storm_c, trade_waste_cents=tw_c))

        if "billing_zone" in rulings and any(by_zone_litres.values()):
            best = max(by_zone_litres.values())
            zone_code = sorted(z for z in by_zone_litres if by_zone_litres[z] == best)[0]
        else:
            pool = alive if alive else P[acc_id]
            zone_code = sorted(pool, key=lambda x: (_day(x["connected_on"]), x["property_id"]))[0]["zone"]
        zinfo = rules["zones"][zone_code]
        svc_all = sums["svc"] + sums["storm"]
        vol = sums["water"] + sums["ww"]
        base = vol + svc_all
        rate_ppm = rules["surcharge"][zinfo["region"]] + (rules["dsupp"] if zinfo["drought"] else 0)
        sur = _div_round(base * rate_ppm, 1_000_000, False)
        supply = base + sur
        levy = _div_round(sums["levy_base"] * rules["catch"], 1_000_000, True)
        gross = supply + levy + sums["trade"]
        named = {"volumetric": vol, "water": sums["water"], "service": svc_all, "supply": supply, "gross": gross}
        ctx = dict(acls=a["account_class"], form=a["holder_form"], card=a["concession_card"],
                   dprop=any(rules["zones"][x["zone"]]["drought"] for x in P.get(acc_id, [])),
                   comm=a["account_class"] == "public" or a["holder_form"] == "association",
                   large=any(r["size_mm"] >= 80 and r["service_days"] > 0 for r in mrows))

        spend = {}
        for c in sorted(CL.get(acc_id, []), key=lambda x: x["claim_id"]):
            rb = code_map.get(c["rebate_code"])
            why = None
            if rb is None:
                why = "no such rebate"
            elif rb["basis"] != "claim":
                why = "rebate arises without claim"
            elif not _qualifies(rb, ctx):
                why = "account not eligible"
            if why:
                notes.append("%s: claim %s under %s disregarded: %s" % (acc_id, c["claim_id"], c["rebate_code"], why))
            else:
                spend[rb["code"]] = spend.get(rb["code"], 0) + int(c["expenditure_cents"])
        leak_rb = [rb for rb in rules["rebates"] if rb["basis"] == "leak"]
        leak_total = 0
        for pr in sorted(P.get(acc_id, []), key=lambda x: x["property_id"]):
            for lc in sorted(LK.get(pr["property_id"], []), key=lambda x: x["leak_claim_id"]):
                fixed_on = _day(lc["repaired_on"])
                if fixed_on < _START or fixed_on > _END:
                    notes.append("%s: leak claim %s disregarded: repair date outside the tariff year" % (acc_id, lc["leak_claim_id"]))
                elif not leak_rb or not _qualifies(leak_rb[0], ctx):
                    notes.append("%s: leak claim %s disregarded: account not eligible" % (acc_id, lc["leak_claim_id"]))
                else:
                    top_rate = _figure_on(rules["classes"][pr["tariff_class"]]["rates"]["block_3"], fixed_on)
                    leak_total += _div_round(int(lc["leak_litres"]) * top_rate * leak_rb[0]["rate_percent"], 10_000_000, False)
        brought = {}
        for e in CF.get(acc_id, []):
            rb = code_map.get(e["rebate_code"])
            yr = int(e["origin_year"])
            if rb is None or not rb["carry_years"]:
                notes.append("%s: carryforward %s/%d disregarded: not permitted" % (acc_id, e["rebate_code"], yr))
            elif 2026 - yr > rb["carry_years"]:
                notes.append("%s: carryforward %s/%d disregarded: expired" % (acc_id, e["rebate_code"], yr))
            else:
                brought.setdefault(rb["code"], []).append((yr, int(e["remaining_cents"])))

        left_to_meet = gross
        overall = _div_round(gross * rules["gcap"], 100, False)
        used_rows, onward = [], []
        for rb in rules["rebates"]:
            code = rb["code"]
            if rb["basis"] == "claim":
                this_year = _div_round(spend[code] * rb["rate_percent"], 100, False) if code in spend else 0
            elif rb["basis"] == "leak":
                this_year = leak_total
            elif _qualifies(rb, ctx):
                on = {"service_pct": svc_all, "water_pct": sums["water"], "large_meter": sums["big"]}[rb["basis"]]
                this_year = _div_round(on * rb["rate_percent"], 100, False)
            else:
                this_year = 0
            queue = sorted(brought.get(code, []))
            if this_year > 0:
                if "current_first" in rulings:
                    queue.insert(0, (2026, this_year))
                else:
                    queue.append((2026, this_year))
            if not queue:
                continue
            lim = rb["cap"]
            room = None if lim is None else (lim[1] if lim[0] == "fixed" else _div_round(named[lim[0]] * lim[1], 100, False))
            for yr, amt in queue:
                cands = [amt, left_to_meet, overall] + ([] if room is None else [room])
                give = max(0, min(cands))
                if give > 0:
                    used_rows.append(dict(rebate_code=code, origin_year=yr, applied_cents=give))
                left_to_meet -= give
                overall -= give
                room = None if room is None else room - give
                rest = amt - give
                if rest > 0 and rb["carry_years"] and 2027 - yr <= rb["carry_years"]:
                    onward.append(dict(rebate_code=code, origin_year=yr, remaining_cents=rest))
        reb_sum = sum(x["applied_cents"] for x in used_rows)
        floor_c = rules["minimum"][a["account_class"]]
        if "minimum_proration" in rulings:
            floor_c = _div_round(floor_c * n_active, 365, True)
        topup = floor_c - (gross - reb_sum) if floor_c > gross - reb_sum else 0
        net = gross - reb_sum + topup

        share = net // 4
        sched = []
        for qq in ("Q1", "Q2", "Q3", "Q4"):
            sched.append(dict(quarter=qq, due=due_of[qq], amount_cents=net - 3 * share if qq == "Q4" else share, paid_cents=0, interest_cents=0))
        grace_end = _dt.timedelta(days=rules["grace"])
        ledger = []
        for pay in PY.get(acc_id, []):
            on_day = _day(pay["paid_on"])
            if on_day > assess_day:
                notes.append("%s: payment %s dated after the assessment date disregarded" % (acc_id, pay["payment_id"]))
                continue
            eff = on_day
            if "payment_day" in rulings:
                while eff.weekday() > 4 or eff in hols:
                    eff += _ONE
            ledger.append((eff, pay["payment_id"], int(pay["amount_cents"])))
        ledger.sort()
        received = sum(x[2] for x in ledger)
        for eff, _pid, amt in ledger:
            for row in sched:
                if not amt:
                    break
                owing = row["amount_cents"] - row["paid_cents"]
                if owing > 0:
                    part = amt if amt < owing else owing
                    row["paid_cents"] += part
                    amt -= part
                    if eff > row["due"] + grace_end:
                        row["interest_cents"] += _interest_on(rules, part, row["due"], eff)
        inst_out = []
        for row in sched:
            owing = row["amount_cents"] - row["paid_cents"]
            if owing > 0 and assess_day > row["due"] + grace_end:
                row["interest_cents"] += _interest_on(rules, owing, row["due"], assess_day)
            inst_out.append(dict(quarter=row["quarter"], due_date=row["due"].isoformat(), amount_cents=row["amount_cents"],
                                 paid_cents=row["paid_cents"], interest_cents=row["interest_cents"]))
        int_total = sum(x["interest_cents"] for x in inst_out)
        onward.sort(key=lambda x: (x["rebate_code"], x["origin_year"]))
        lines.sort(key=lambda x: (x["meter_id"], x["to"]))
        rec = dict(account_id=acc_id, account_class=a["account_class"], holder_form=a["holder_form"], concession_card=a["concession_card"],
                   active_days=n_active, billing_zone=zone_code, meter_intervals=lines, meters=mrows, properties=prows)
        rec.update(water_supply_cents=sums["water"], wastewater_cents=sums["ww"], volumetric_charges_cents=vol, service_charges_cents=svc_all,
                   base_charges_cents=base, surcharge_cents=sur, supply_total_cents=supply, catchment_levy_cents=levy,
                   trade_waste_cents=sums["trade"], gross_charge_cents=gross)
        rec.update(rebates_applied=used_rows, rebates_total_cents=reb_sum, carryforward_out=onward, minimum_charge_cents=floor_c,
                   minimum_topup_cents=topup, net_charge_cents=net, instalments=inst_out, payments_cents=received,
                   interest_cents=int_total, balance_cents=net + int_total - received)
        assessed.append((zinfo["region"], rec))

    def roll(recs):
        return {f: sum(r[f] for r in recs) for f in _SUM_FIELDS}
    everyone = [r for _, r in assessed]
    docs = {}
    docs["summary.json"] = dict(
        report_id=manifest["batch_id"], assessment_date=manifest["assessment_date"], account_count=len(everyone), totals=roll(everyone),
        region_totals={g: roll([r for z, r in assessed if z == g]) for g in _REGION_ORDER},
        class_account_counts={c: len([r for r in everyone if r["account_class"] == c]) for c in ("residential", "commercial", "public")},
        balance_status_counts=dict(credit_balance=len([r for r in everyone if r["balance_cents"] < 0]),
                                   settled=len([r for r in everyone if r["balance_cents"] == 0]),
                                   balance_due=len([r for r in everyone if r["balance_cents"] > 0])))
    audit = dict(rules["audit"])
    audit["report_id"] = manifest["batch_id"]
    docs["policy_audit.json"] = audit
    docs["data_quality.json"] = dict(
        input_file_count=sum(1 for p in data_dir.iterdir() if p.is_file()), account_count=len(T["accounts.csv"]),
        property_count=len(T["properties.csv"]), meter_count=len(T["meters.csv"]), reading_count=len(T["meter_reads.csv"]),
        trade_waste_return_count=len(T["trade_waste.csv"]), claim_count=len(T["concession_claims.csv"]),
        leak_claim_count=len(T["leak_claims.csv"]), carryforward_count=len(T["carryforwards.csv"]), payment_count=len(T["payments.csv"]),
        quality_issue_count=len(notes), quality_issues=sorted(notes))
    for g in _REGION_ORDER:
        mine = [r for z, r in assessed if z == g]
        docs["region_%s.json" % g] = dict(region=g, account_count=len(mine), totals=roll(mine), accounts=mine)
    for seg in ("commercial", "public"):
        mine = [r for r in everyone if r["account_class"] == seg]
        per_code = {}
        for r in mine:
            for row in r["rebates_applied"]:
                per_code[row["rebate_code"]] = per_code.get(row["rebate_code"], 0) + row["applied_cents"]
        docs["segment_%s.json" % seg] = dict(segment=seg, account_count=len(mine), totals=roll(mine), rebate_totals=per_code,
                                             account_ids=[r["account_id"] for r in mine])
    return docs


