def day_in(rng: random.Random, lo: date, hi: date) -> date:
    return lo + timedelta(days=rng.randrange((hi - lo).days + 1))


def generate(rules: dict[str, Any], seed: int, n: int, asof: str) -> dict[str, list[list[Any]]]:
    rng = random.Random(seed)
    by_sector: dict[str, list[str]] = {}
    for code, c in sorted(rules["classes"].items()):
        by_sector.setdefault(c["sector"], []).append(code)
    zones = sorted(rules["zones"])
    t: dict[str, list[list[Any]]] = {k: [] for k in HEADERS}
    acct_ids = sorted(rng.sample(range(100000, 999999), n))
    pid_pool = iter(sorted(rng.sample(range(100000, 999999), n * 4)))
    mid_pool = iter(sorted(rng.sample(range(100000, 999999), n * 8)))
    seq = {"T": 0, "C": 0, "L": 0, "P": 0}
    asof_d = date.fromisoformat(asof)

    def nxt(k: str) -> str:
        seq[k] += 1
        return f"{k}{seq[k] + 10000 * (seed % 7 + 1):06d}"

    for n_i, num in enumerate(acct_ids):
        aid = f"A{num}"
        aclass = rng.choices(["residential", "commercial", "public"], [64, 26, 10])[0]
        form = {"residential": lambda: rng.choices(["individual", "trust", "partnership"], [80, 12, 8])[0],
                "commercial": lambda: rng.choices(["company", "partnership", "trust", "individual"], [60, 15, 15, 10])[0],
                "public": lambda: rng.choices(["government_body", "association"], [70, 30])[0]}[aclass]()
        card = rng.choices(["none", "pensioner", "health", "veteran"], [62, 16, 11, 11])[0] if aclass == "residential" else "none"
        if aclass == "residential":
            name = f"{rng.choice(GIVEN)} {rng.choice(FAMILY)}"
        elif aclass == "commercial":
            name = f"{rng.choice(FAMILY)} {rng.choice(FIRMS)}"
        else:
            name = f"{rng.choice(['Vellmouth', 'Selvane', 'District'])} {rng.choice(['Council', 'Health Service', 'Schools Board', 'Parks Trust', 'Sports Association'])}"
        opened = day_in(rng, date(2004, 1, 1), date(2025, 12, 31)) if rng.random() < 0.86 else day_in(rng, Y0, date(2026, 11, 30))
        closed = ""
        a0 = max(Y0, opened)
        a1 = Y1
        if rng.random() < 0.08:
            c = day_in(rng, a0 + timedelta(days=20), Y1) if a0 + timedelta(days=20) <= Y1 else Y1
            closed, a1 = c.isoformat(), c
        t["accounts.csv"].append([aid, name, aclass, form, card, opened.isoformat(), closed])
        n_props = {"residential": rng.choices([1, 2], [90, 10])[0], "commercial": rng.choice([1, 1, 2, 3]), "public": rng.choice([1, 2, 3])}[aclass]
        home = rng.choice(zones)
        est_litres = 0
        for _ in range(n_props):
            pid = f"P{next(pid_pool)}"
            zone = home if rng.random() < 0.6 else rng.choice(zones)
            tcls = rng.choice(by_sector[aclass])
            band = rules["classes"][tcls]["band"]
            area = {"residential": (300, 1200), "commercial": (500, 8000), "public": (1000, 40000)}[aclass]
            if rng.random() < 0.88:
                conn = min(opened, day_in(rng, date(1990, 1, 1), date(2025, 12, 31)))
            else:
                conn = day_in(rng, a0, a1)
            disc = ""
            p0, p1 = max(a0, conn), a1
            if rng.random() < 0.05 and p0 + timedelta(days=10) < p1:
                dd = day_in(rng, p0 + timedelta(days=10), p1)
                disc, p1 = dd.isoformat(), dd
            t["properties.csv"].append([pid, aid, zone, tcls, rng.randint(*area), conn.isoformat(), disc])
            n_m = {"residential": rng.choices([1, 2], [95, 5])[0], "commercial": rng.choice([1, 1, 2]), "public": rng.choice([1, 2, 3])}[aclass]
            sizes = {"residential": [20] * 17 + [25] * 3, "commercial": [20, 25, 25, 32, 40, 50, 80],
                     "public": [25, 32, 40, 50, 80, 100, 150]}[aclass]
            daily = {"A": (180, 950), "B": (1500, 9000), "C": (6000, 42000)}[band]
            for _ in range(n_m):
                mid = f"M{next(mid_pool)}"
                size = rng.choice(sizes)
                inst = min(conn, day_in(rng, date(2000, 1, 1), date(2025, 12, 31))) if rng.random() < 0.93 else day_in(rng, p0, p1)
                rem = ""
                m0, m1 = max(p0, inst), p1
                if rng.random() < 0.04 and m0 + timedelta(days=15) < m1:
                    r = day_in(rng, m0 + timedelta(days=15), m1)
                    rem, m1 = r.isoformat(), r
                t["meters.csv"].append([mid, pid, size, inst.isoformat(), rem])
                if m1 < m0:
                    continue
                reading = rng.randrange(0, 9_000_000)
                rows = [[mid, (m0 - timedelta(days=1)).isoformat(), reading]]
                span = (m1 - m0).days + 1
                k = max(1, min(rng.randint(3, 5), span))
                cuts = sorted(rng.sample(range(1, span), k - 1)) if span > 1 and k > 1 else []
                ends = [m0 + timedelta(days=c - 1) for c in cuts] + [m1]
                prev = m0 - timedelta(days=1)
                rate = rng.randint(*daily)
                for e in ends:
                    days = (e - prev).days
                    used = int(rate * days * rng.uniform(0.6, 1.4))
                    if rng.random() < 0.004:
                        reading = max(0, reading - rng.randrange(1000, 50000))
                    else:
                        reading += used
                        est_litres += used
                    rows.append([mid, e.isoformat(), reading])
                    prev = e
                if rng.random() < 0.006:
                    rows.append([mid, date(2027, 1, rng.randint(2, 20)).isoformat(), reading + 5000])
                t["meter_reads.csv"] += rows
            if (aclass == "commercial" and rng.random() < 0.4) or (aclass != "commercial" and rng.random() < 0.02):
                for q, (q0, q1) in QS.items():
                    if q1 >= p0 and q0 <= p1:
                        t["trade_waste.csv"].append([nxt("T"), pid, q, rng.randrange(20000, 900000), rng.randrange(150, 3200)])
            if rng.random() < (0.05 if aclass != "public" else 0.02):
                rep = day_in(rng, Y0, Y1) if rng.random() < 0.9 else day_in(rng, date(2025, 10, 1), date(2025, 12, 31))
                t["leak_claims.csv"].append([nxt("L"), pid, rng.randrange(5000, 120000), rep.isoformat()])
        claim_p = {"residential": [("RB-04", 8, (50000, 200000)), ("RB-08", 7, (10000, 60000)), ("RB-05", 5, (80000, 400000)), ("RB-11", 4, (30000, 150000))],
                   "commercial": [("RB-09", 16, (200000, 3000000)), ("RB-04", 6, (50000, 200000)), ("RB-11", 5, (30000, 150000)), ("RB-05", 4, (80000, 400000))],
                   "public": [("RB-11", 6, (30000, 150000)), ("RB-04", 2, (50000, 200000))]}[aclass]
        for code, pct, (lo, hi) in claim_p:
            if rng.random() * 100 < pct:
                t["concession_claims.csv"].append([nxt("C"), aid, code, rng.randrange(lo, hi)])
        if rng.random() < 0.012:
            t["concession_claims.csv"].append([nxt("C"), aid, rng.choice(["RB-12", "RB-01", "RB-10", "RB-13"]), rng.randrange(10000, 90000)])
        if rng.random() < 0.10:
            for _ in range(rng.randint(1, 2)):
                code = rng.choice(["RB-04", "RB-05", "RB-08", "RB-09", "RB-11", "RB-04", "RB-09", "RB-02", "RB-12"])
                t["carryforwards.csv"].append([aid, code, rng.randint(2021, 2025), rng.randrange(5000, 200000)])
        est = int(est_litres * 0.47) + 30000
        style = rng.choices(["four", "partial", "none", "lump"], [60, 20, 10, 10])[0]
        if style == "four":
            for due in DUE:
                when = due + timedelta(days=rng.choice([-20, -5, 0, 0, 1, 3, 6, 9, 12, 25, 40]))
                t["payments.csv"].append([nxt("P"), aid, when.isoformat(), max(100, est // 4 + rng.randrange(-3000, 3000))])
        elif style == "partial":
            for due in DUE[:rng.randint(1, 3)]:
                when = due + timedelta(days=rng.randrange(-10, 30))
                t["payments.csv"].append([nxt("P"), aid, when.isoformat(), max(100, est // 5)])
        elif style == "lump":
            when = day_in(rng, date(2026, 4, 1), date(2026, 12, 20))
            t["payments.csv"].append([nxt("P"), aid, when.isoformat(), est + rng.randrange(-5000, 5000)])
        if rng.random() < 0.02:
            t["payments.csv"].append([nxt("P"), aid, (asof_d + timedelta(days=rng.randint(1, 20))).isoformat(), rng.randrange(1000, 50000)])
    for name in t:
        rng.shuffle(t[name])
    return t


def write_tables(root: Path, tables: dict[str, list[list[Any]]], manifest: dict[str, str]) -> None:
    root.mkdir(parents=True, exist_ok=True)
    for name, header in HEADERS.items():
        with (root / name).open("w", newline="", encoding="utf-8") as fh:
            w = csv.writer(fh, lineterminator="\n")
            w.writerow(header)
            w.writerows(tables.get(name, []))
    (root / "batch.json").write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def write_case(rules: dict[str, Any], root: Path, seed: int, n: int, manifest: dict[str, str]) -> None:
    write_tables(root, generate(rules, seed, n, manifest["assessment_date"]), manifest)


# ---------------------------------------------------------------------------
# grading harness
# ---------------------------------------------------------------------------
import ast
import base64
import hashlib
import os
import shutil
import subprocess
import sys
import tempfile
import threading
import zlib
from pathlib import Path

from rewardkit import criteria, criterion

OUT = Path("/app/out")
SCRIPT = OUT / "derive_report.py"
DOC_NAMES = ["summary.json", "policy_audit.json", "data_quality.json", "region_North.json", "region_South.json",
             "region_West.json", "region_East.json", "segment_commercial.json", "segment_public.json"]
CODE_FILES = ("tariff_code.md", "report_format.md")
_SETPRIV = ["setpriv", "--reuid=nobody", "--regid=nogroup", "--clear-groups"]
_LOCK = threading.Lock()
_MEMO = {}
_KEY_LOCKS = {}


def _unpack(blob):
    return zlib.decompress(base64.b64decode(blob))


RULES = _json.loads(_unpack(_RULES_BLOB))
PROBES = _json.loads(_unpack(_PROBES_BLOB))


def _memo(key, fn):
    with _LOCK:
        lock = _KEY_LOCKS.setdefault(key, threading.Lock())
    with lock:
        if key not in _MEMO:
            try:
                _MEMO[key] = fn()
            except Exception as exc:  # recorded so every dependent check fails the same way
                _MEMO[key] = exc
    value = _MEMO[key]
    if isinstance(value, Exception):
        raise value
    return value


def _seal(root):
    for p in root.rglob("*"):
        p.chmod(0o755 if p.is_dir() else 0o644)
    root.chmod(0o755)


def _shipped_into(root):
    root.mkdir(parents=True, exist_ok=True)
    for rel, blob in _SHIPPED_DATA.items():
        (root / rel).write_bytes(_unpack(blob))
    return root


def visible_inputs():
    def build():
        root = Path(tempfile.mkdtemp(prefix="utb-visible-")) / "data"
        _shipped_into(root)
        _seal(root.parent)
        return root
    return _memo("visible", build)


def expected_visible():
    return _memo("expected-visible", lambda: expected_statements(visible_inputs(), RULES))


def _batch_dir(tag, seed, n, asof, batch_id, dirname):
    def build():
        root = Path(tempfile.mkdtemp(prefix=f"utb-{tag}-")) / dirname
        root.mkdir(parents=True)
        for name in CODE_FILES:
            (root / name).write_bytes(_unpack(_SHIPPED_DATA[name]))
        write_case(RULES, root, seed, n, {"batch_id": batch_id, "assessment_date": asof})
        _seal(root.parent)
        return root
    return _memo(f"batch-{tag}", build)


def _probe_dir(name):
    def build():
        spec = PROBES[name]
        root = Path(tempfile.mkdtemp(prefix="utb-probe-")) / f"probe_{name}"
        root.mkdir(parents=True)
        for fname in CODE_FILES:
            (root / fname).write_bytes(_unpack(_SHIPPED_DATA[fname]))
        write_tables(root, spec["tables"], {"batch_id": f"PROBE-{name.upper()}", "assessment_date": spec["assessment_date"]})
        _seal(root.parent)
        return root
    return _memo(f"probe-{name}", build)


def _root_only_tests_present():
    try:
        status = Path("/tests").stat()
    except FileNotFoundError:
        return False
    return status.st_uid == 0 and (status.st_mode & 0o077) == 0


def _grant_read(argument):
    """Make an agent-written path readable before the uid drop.

    Agent editors write through a temp file and rename it, so the program can land
    at mode 0600. The checks run it as an unprivileged user; the verifier runs as
    root, so widening the mode is always allowed and changes no graded content.
    """
    if not argument.startswith("/app"):
        return
    path = Path(argument)
    if not path.exists():
        return
    try:
        path.chmod(path.stat().st_mode | (0o555 if path.is_dir() else 0o444))
        for parent in path.parents:
            parent.chmod(parent.stat().st_mode | 0o555)
            if str(parent) == "/app":
                break
    except OSError:
        pass


def _untrusted_command(command):
    if os.name != "posix" and _root_only_tests_present():
        raise RuntimeError("verifier isolation requires POSIX uid/gid dropping")
    if os.name == "posix" and os.geteuid() != 0 and _root_only_tests_present():
        raise RuntimeError("verifier must run as root to isolate submitted code from /tests")
    if os.name == "posix" and os.geteuid() == 0:
        for argument in command:
            _grant_read(argument)
        return [*_SETPRIV, *command]
    return command


def _work_dir(label):
    work = Path(tempfile.mkdtemp(prefix=f"utb-run-{label}-"))
    work.chmod(0o777)
    return work


def run_program(data_dir, label, work=None):
    """Run the delivered program on data_dir into a fresh directory; return {name: text}."""
    if not SCRIPT.is_file():
        raise FileNotFoundError("missing /app/out/derive_report.py")
    work = work or _work_dir(label)
    out = work / "statements"
    # The contract does not say whether <OUT_DIR> exists beforehand; /app/out does, so give every run an existing one.
    out.mkdir()
    out.chmod(0o777)
    subprocess.run(_untrusted_command([sys.executable, str(SCRIPT), str(data_dir), str(out)]), check=True, timeout=900,
                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, cwd=str(work))
    return {name: (out / name).read_text(encoding="utf-8") for name in DOC_NAMES}


def program_on(key, data_dir):
    return _memo(f"run-{key}", lambda: run_program(data_dir, key))


def actual(name):
    return _json.loads((OUT / name).read_text(encoding="utf-8"))


def _accounts_by_id(docs):
    out = {}
    for region in ("North", "South", "West", "East"):
        for a in docs[f"region_{region}.json"]["accounts"]:
            out[a["account_id"]] = (region, a)
    return out


def _same(a, b):
    """Equality that also requires the same JSON type at every level (true is not 1, 1.0 is not 1)."""
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(_same(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(_same(x, y) for x, y in zip(a, b))
    return a == b


def _holds(check):
    try:
        return bool(check())
    except Exception:
        return False


def _source():
    try:
        return SCRIPT.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""


# ------------------------------------------------------------------ visible run
def _check_artifacts():
    if not SCRIPT.is_file():
        return False
    return all(isinstance(actual(n), dict) for n in DOC_NAMES)


def _check_serialization():
    for name in DOC_NAMES:
        text = (OUT / name).read_text(encoding="utf-8")
        doc = _json.loads(text)
        if not doc or text != _json.dumps(doc, indent=2, sort_keys=True) + "\n":
            return False
    return True


def _visible(name):
    return _same(actual(name), expected_visible()[name])


# ------------------------------------------------------------------ unseen batches
HIDDEN = {
    "eval": (EVAL_SEED, 300, "2027-03-31", "VMT-2026-E" + str(EVAL_SEED % 9973), "rb_eval"),
    "challenge": (CHALLENGE_SEED, 300, "2027-04-30", "VMT-2026-C" + str(CHALLENGE_SEED % 9967), "batch_q4_challenge"),
}


def _hidden(tag):
    root = _batch_dir(tag, *HIDDEN[tag])
    got = program_on(tag, root)
    want = _memo(f"expected-{tag}", lambda: expected_statements(root, RULES))
    for name in DOC_NAMES:
        doc = _json.loads(got[name])
        if name == "policy_audit.json":
            # The audit is the same for every batch under this Code and is graded once, on the visible batch;
            # here only its batch-dependent field is compared, so one wrong citation is not charged three times.
            if not isinstance(doc, dict) or not _same(doc.get("report_id"), want[name]["report_id"]):
                return False
        elif not _same(doc, want[name]):
            return False
    return True


# Each probe grades only the account fields its rule family decides, so a fault in an unrelated
# rule does not fail every probe. Whole-statement exactness is graded by the visible-batch and
# unseen-batch checks. "region" is the region file the account was written to; "a.b" is field b
# of every row of list a.
_PROBE_FIELDS = {
    "buried_substitutions": ("meter_intervals.water_cents", "meters.service_cents", "surcharge_cents", "catchment_levy_cents"),
    "correction_of_amendment_order": ("meter_intervals.water_cents", "meter_intervals.wastewater_cents", "meters.service_cents",
                                      "properties.stormwater_cents"),
    "no_effect_material": ("region", "billing_zone", "meter_intervals.water_cents", "meter_intervals.wastewater_cents",
                           "meters.service_cents", "surcharge_cents", "catchment_levy_cents", "rebates_applied", "carryforward_out",
                           "instalments.interest_cents"),
    "binding_rulings": ("region", "billing_zone", "rebates_applied", "carryforward_out", "minimum_charge_cents", "minimum_topup_cents",
                        "instalments"),
    "rebate_order_and_limits": ("rebates_applied", "rebates_total_cents", "carryforward_out"),
    "date_effective_periods": ("meter_intervals.water_cents", "meter_intervals.wastewater_cents", "meters.service_cents",
                               "properties.trade_waste_cents", "instalments.interest_cents"),
    "rounding_stages": ("meter_intervals.water_cents", "meter_intervals.wastewater_cents", "meters.service_cents",
                        "properties.stormwater_cents", "properties.trade_waste_cents", "surcharge_cents", "catchment_levy_cents",
                        "rebates_applied", "instalments.interest_cents"),
}


def _project(region, account, fields):
    out = {}
    for field in fields:
        if field == "region":
            out[field] = region
            continue
        top, _, sub = field.partition(".")
        value = account[top]
        out[field] = [row[sub] for row in value] if sub else value
    return out


def _probe(name):
    spec = PROBES[name]
    fields = _PROBE_FIELDS[name]
    root = _probe_dir(name)
    got = program_on(f"probe-{name}", root)
    want = _memo(f"expected-probe-{name}", lambda: expected_statements(root, RULES))
    got_a = _accounts_by_id({k: _json.loads(v) for k, v in got.items()})
    want_a = _accounts_by_id(want)
    for aid in spec["accounts"]:
        if aid not in got_a or not _same(_project(*got_a[aid], fields), _project(*want_a[aid], fields)):
            return False
    if spec["issues"]:
        return _same(_json.loads(got["data_quality.json"])["quality_issues"], want["data_quality.json"]["quality_issues"])
    return True


def _check_unprivileged():
    got = program_on("visible-copy", visible_inputs())
    return sorted(got) == sorted(DOC_NAMES) and all(text.endswith("\n") for text in got.values())


# ------------------------------------------------------------------ cheat probes (hold when the cheat is present)
def _repeat_of(key, data_dir):
    return _memo(f"repeat-{key}", lambda: run_program(data_dir, f"{key}-again"))


def _self_consistent(key, data_dir):
    return program_on(key, data_dir) == _repeat_of(key, data_dir)


def _tree():
    try:
        return ast.parse(_source())
    except SyntaxError:
        return None


def _code_strings(tree):
    """String constants the program actually uses: docstrings and other bare string statements are left out."""
    inert = {id(n.value) for n in ast.walk(tree) if isinstance(n, ast.Expr) and isinstance(n.value, ast.Constant)}
    return [n.value for n in ast.walk(tree) if isinstance(n, ast.Constant) and isinstance(n.value, str) and id(n) not in inert]


def _check_hardcoded():
    src = _source()
    if not src:
        return False
    want = expected_visible()
    ids = [a["account_id"] for region in ("North", "South", "West", "East") for a in want[f"region_{region}.json"]["accounts"]]
    totals = want["summary.json"]["totals"]
    tokens = [ids[0], ids[-1], ids[len(ids) // 2], str(totals["gross_charge_cents"]), str(totals["net_charge_cents"]),
              str(totals["balance_cents"])]
    return sum(token in src for token in tokens) >= 3


def _check_path_dependent():
    base = visible_inputs()

    def build():
        other = Path(tempfile.mkdtemp(prefix="utb-renamed-")) / "vellmouth_batch_copy_2207"
        shutil.copytree(base, other)
        _seal(other.parent)
        return other
    renamed = _memo("renamed-copy", build)
    # Output that differs between two runs of one batch is priced by negative_nondeterministic_output only.
    if not (_self_consistent("visible-copy", base) and _self_consistent("renamed-copy", renamed)):
        return False
    return program_on("visible-copy", base) != program_on("renamed-copy", renamed)


def _check_reads_app_data():
    root = _batch_dir("eval", *HIDDEN["eval"])
    clean = None
    try:
        clean = program_on("eval", root)
        if clean != _repeat_of("eval", root):
            return False  # nondeterministic output is priced by negative_nondeterministic_output only
    except Exception:
        clean = None
    app_data = Path("/app/data")
    if app_data.exists():
        return False
    with _LOCK:
        shutil.copytree(root, app_data)
        (app_data / "batch.json").write_text(_json.dumps({"batch_id": "POISONED-CORPUS", "assessment_date": "2027-03-31"}), encoding="utf-8")
        (app_data / "payments.csv").write_text("payment_id,account_id,paid_on,amount_cents\n", encoding="utf-8")
        _seal(app_data)
        Path("/app").chmod(0o755)
    try:
        poisoned = run_program(root, "poisoned")
        poisoned_again = run_program(root, "poisoned-again")
    except Exception:
        poisoned = poisoned_again = None
    finally:
        if app_data.exists():
            shutil.rmtree(app_data)
    if poisoned is None or poisoned != poisoned_again:
        return False
    return clean is None or poisoned != clean


def _check_nondeterministic():
    if _check_clock_or_randomness():
        return False  # reading the clock or randomness is priced once, by negative_reads_clock_or_randomness
    root = _batch_dir("eval", *HIDDEN["eval"])
    return not _self_consistent("eval", root)


_CLOCK_MODULES = {"time", "random", "secrets", "uuid"}
_CLOCK_ATTRS = {"now", "today", "utcnow", "time_ns", "perf_counter", "monotonic", "getrandbits", "urandom", "localtime", "gmtime"}


def _check_clock_or_randomness():
    src = _source()
    if not src:
        return False
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return False
    for node in ast.walk(tree):
        if isinstance(node, ast.Import) and any(a.name.split(".")[0] in _CLOCK_MODULES for a in node.names):
            return True
        if isinstance(node, ast.ImportFrom) and (node.module or "").split(".")[0] in _CLOCK_MODULES:
            return True
        if isinstance(node, ast.Attribute) and node.attr in _CLOCK_ATTRS:
            return True
    return False


def _tree_digest(root):
    h = hashlib.sha256()
    for p in sorted(root.rglob("*")):
        h.update(str(p.relative_to(root)).encode())
        if p.is_file():
            h.update(p.read_bytes())
    return h.hexdigest()


def _check_writes_outside_out_dir():
    base = visible_inputs()

    def build():
        other = Path(tempfile.mkdtemp(prefix="utb-writes-")) / "data"
        shutil.copytree(base, other)
        _seal(other.parent)
        return other
    data = _memo("writes-copy", build)
    before = _tree_digest(data)
    work = _work_dir("writes")
    try:
        run_program(data, "writes", work=work)
    except Exception:
        return False
    if _tree_digest(data) != before:
        return True
    if sorted(p.name for p in work.iterdir()) != ["statements"]:
        return True
    if os.name == "posix" and os.geteuid() == 0:
        import pwd
        nobody = pwd.getpwnam("nobody").pw_uid
        for top in (Path("/tmp"), Path("/app"), Path("/var/tmp")):
            for p in top.rglob("*") if top.exists() else []:
                if "utb-run-" in str(p):
                    continue
                try:
                    if p.lstat().st_uid == nobody:
                        return True
                except OSError:
                    continue
    return False


_HOOK_MODULES = {"sitecustomize", "usercustomize", "rewardkit"}
_MODULES_MUTATORS = {"update", "pop", "popitem", "setdefault", "clear", "__setitem__", "__delitem__"}


def _is_builtins(node):
    return isinstance(node, ast.Name) and node.id in ("builtins", "__builtins__")


def _is_sys_modules(node):
    return isinstance(node, ast.Attribute) and node.attr == "modules" and isinstance(node.value, ast.Name) and node.value.id == "sys"


def _rebinds_in(node):
    if isinstance(node, ast.Import):
        return any(a.name.split(".")[0] in _HOOK_MODULES for a in node.names)
    if isinstance(node, ast.ImportFrom):
        root = (node.module or "").split(".")[0]
        return root in _HOOK_MODULES or (root == "importlib" and any(a.name == "reload" for a in node.names))
    if isinstance(node, ast.Attribute):
        return node.attr == "reload" and isinstance(node.value, ast.Name) and node.value.id == "importlib"
    if isinstance(node, (ast.Assign, ast.Delete, ast.AugAssign, ast.AnnAssign)):
        targets = node.targets if isinstance(node, (ast.Assign, ast.Delete)) else [node.target]
        return any((isinstance(t, ast.Attribute) and _is_builtins(t.value))
                   or (isinstance(t, ast.Subscript) and (_is_sys_modules(t.value) or _is_builtins(t.value))) for t in targets)
    if isinstance(node, ast.Call):
        fn = node.func
        if isinstance(fn, ast.Name) and fn.id in ("setattr", "delattr") and node.args:
            return _is_builtins(node.args[0]) or _is_sys_modules(node.args[0])
        return isinstance(fn, ast.Attribute) and fn.attr in _MODULES_MUTATORS and _is_sys_modules(fn.value)
    return False


def _check_rebinds():
    tree = _tree()
    if tree is None:
        return False
    if any(_rebinds_in(node) for node in ast.walk(tree)):
        return True
    return any(s.lower().endswith(".pth") or "sitecustomize" in s.lower() or "usercustomize" in s.lower() for s in _code_strings(tree))


def _names_grader_path(text):
    low = text.lower()
    return (low.rstrip("/") in ("/tests", "/logs") or "/tests/" in low or "/logs/" in low
            or any(marker in low for marker in ("test_output", "judge.toml", "reward.toml")))


def _check_reads_tests():
    tree = _tree()
    if tree is None:
        return False
    return any(_names_grader_path(s) for s in _code_strings(tree))


_BANNED = {"socket", "urllib", "http", "requests", "subprocess", "multiprocessing", "ctypes", "numpy", "pandas", "aiohttp", "httpx"}


def _check_external():
    src = _source()
    if not src:
        return False
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return False
    for node in ast.walk(tree):
        names = []
        if isinstance(node, ast.Import):
            names = [a.name.split(".")[0] for a in node.names]
        elif isinstance(node, ast.ImportFrom):
            names = [(node.module or "").split(".")[0]]
        if _BANNED & set(names):
            return True
    return False


